// Backend: generate a pre signed upload URL for a specific key
const key = `uploads/user-${userId}/original/${photoId}.jpg`;
const uploadUrl = await s3.getSignedUrlPromise('putObject', {
  Bucket: 'photoapp-media',
  Key: key,
  Expires: 300,
  ContentType: 'image/jpeg',
});
// Client then does a PUT of the raw bytes directly to uploadUrl
// The backend only stores photoId, userId, and key in its database

